Simplicite.UI.ExternalObjects.LlmSetup=class extends Simplicite.UI.ExternalObject{constructor(ctn,obj,rowid,data){super(ctn,obj,rowid,data);this.businessObject=$app.getBusinessObject("LlmProvider","setup");this.specificFields=["llmGptOrganizationId","llmGptProjectId","llmAnthropicWorkspaceId"];this.urlFields=["llmPrvPingUrl","llmPrvSttUrl","llmPrvModelsUrl","llmPrvCompletionUrl"];}
async render(params,data){await super.render(params,data);await this.displayEmptyForm(data);return this;}
getSetupContainer(){return $(".llmsetup",this.ctn);}
getFieldContainer(fieldName){return this.getSetupContainer().find('.field[data-field="'+fieldName+'"]');}
getInputById(id){return this.getSetupContainer().find("#"+id);}
loadCurrentSetup(data){if(!data)return;this.modelToRestore=data.llmModel||null;for(const field of Object.keys(data)){const fieldContainer=this.getFieldContainer(field);const formGroup=fieldContainer.find(".form-group");if(field==="llmPrvProvider"){const select=fieldContainer.find('select[name="llmPrvProvider"]');select.val(data[field]);select.trigger("change");}else if(field==="llmModel"){continue;}else{formGroup.find("input").val(data[field]);formGroup.removeClass("hidden");}}
this.getModelsForProviderAndShow();}
async displayEmptyForm(data){const div=this.getSetupContainer();await this.businessObject.getMetaData();div.find(".field").each((i,el)=>{const fieldContainer=$(el);const name=fieldContainer.data("field");const field=$ui.getUIField(fieldContainer,this.businessObject,name,null,false);if(!field)return;if(name==="llmPrvProvider"){const display=field.ui.display();const select=display.find("#field_llmPrvProvider");select.attr("aria-controls","help-block specific_keys urls_zone");select.off("change.llmSetup").on("change.llmSetup",()=>{this.showSpecificKeysForProvider(select.val());});fieldContainer.html(display);}else{const display=field.ui.display();const input=display.find("input");input.val(field.defaultValue).attr("placeholder",field.placeholder||field.defaultValue||"");fieldContainer.html(display);}});if(data?.update?.llmPrvProvider){this.loadCurrentSetup(data.update);}
this.businessObject.beforeSave();this.businessObject.afterSave();}
async service(data,options){return super.service(data,options);}
async showSpecificKeysForProvider(provider){const div=this.getSetupContainer();for(const field of this.specificFields){this.getFieldContainer(field).find(".form-group").addClass("hidden").val("");}
div.find(".field").each((i,el)=>{const fieldContainer=$(el);const name=fieldContainer.data("field");if(name!="llmApiKey"&&name!="llmPrvProvider"){fieldContainer.find(".form-group").addClass("hidden");}});this.addActionButton($grant.T("MCP_FETCH_MLD"),"getModels",div,()=>this.getModelsForProviderAndShow());try{const result=await this.businessObject.search({llmPrvProvider:provider});if(!result||result.length===0)return;const providerData=result[0];let specificKeys=providerData.llmPrvDataModel;if(typeof specificKeys==="string"){specificKeys=JSON.parse(specificKeys||"{}");}
for(const key of Object.keys(specificKeys||{})){this.getFieldContainer(key).find(".form-group").removeClass("hidden");}
this.showUrlForProvider(providerData);this.addHelp(providerData.llmPrvHelp,div);}catch(error){console.error("Erreur lors du chargement des paramètres fournisseur",error);}}
addHelp(help,div=this.getSetupContainer()){div.find("#help-block").empty().html(help||"");}
addActionButton(label,name,div,callback){div.find(".act").empty().append($("<button/>",{type:"button",name:name,class:"btn btn-secondary",text:label}).on("click",callback));}
showUrlForProvider(providerData){for(const field of this.urlFields){const formGroup=this.getFieldContainer(field).find(".form-group");formGroup.removeClass("hidden");formGroup.find("input").val(providerData[field]||"");}}
async getModelsForProviderAndShow(){const div=this.getSetupContainer();const apiKey=this.getInputById("field_llmApiKey").val();const url=this.getInputById("field_llmPrvModelsUrl").val();try{const response=await fetch("/ui/ext/AiMcpClientApi/getModels",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({url:url,apiKey:apiKey})});const result=await response.json();if(result.status===200){this.addModels(result.payload);this.showFields();this.addActionButton($grant.T("MCP_VALIDATE_SETUP"),"validate",div,()=>this.validateSetup());}else{$ui.alert(this.parseError(result.error));}}catch(error){console.error("Erreur lors de la récupération des modèles",error);$ui.alert(this.parseError(error.message));}}
async validateSetup(){const getValue=(id)=>this.getInputById(id).val();const data={completion_url:getValue("field_llmPrvCompletionUrl"),provider:getValue("field_llmPrvProvider"),api_key:getValue("field_llmApiKey"),default_max_token:getValue("field_llmMaxToken"),showDataDisclaimer:getValue("field_llmDataDisclamer"),hist_depth:getValue("field_llmHistoryDepth"),model:getValue("field_llmModel"),model_url:getValue("field_llmPrvModelsUrl"),stt_url:getValue("field_llmPrvSttUrl"),ping_url:getValue("field_llmPrvPingUrl")};try{const result=await this.businessObject.search({llmPrvProvider:data.provider});if(result&&result.length>0){const providerData=result[0];let specificKeys=providerData.llmPrvDataModel;if(typeof specificKeys==="string"){specificKeys=JSON.parse(specificKeys||"{}");}
for(const key of Object.keys(specificKeys||{})){const apiName=specificKeys[key].api_name;if(apiName){data[apiName]=this.getInputById("field_"+key).val();}}}
if(data.provider==="claude"){data.ClaudeAPI=true;}
const response=await fetch("/ui/ext/AiMcpClientApi/setParams",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({llmSettings:data})});const resultResponse=await response.json();const message=JSON.parse(resultResponse.payload);$ui.backendMessage(message,true);}catch(error){console.error("Erreur lors de la validation de la configuration",error);$ui.alert(this.parseError(error.message));}
$ui.displayHome(null,{nav:"new",showNav:true});}
addModels(models){const fieldContainer=this.getFieldContainer("llmModel");const select=fieldContainer.find("#field_llmModel");if(models&&!Array.isArray(models)&&Array.isArray(models.data)){models=models.data;}
if(!Array.isArray(models)){models=[];}
select.empty().append($("<option/>",{class:"enum-empty",value:"",text:""}));models.forEach((model)=>{const id=typeof model==="string"?model:(model.id||model.name);if(!id)return;select.append($("<option/>",{value:id,text:id}));});if(this.modelToRestore){select.val(this.modelToRestore);select.trigger("change");this.modelToRestore=null;}
if(select.data("select2")){select.trigger("change.select2");}else if($.fn.select2){select.select2({width:"100%"});}else{select.trigger("change");}}
showFields(){const div=this.getSetupContainer();div.find(".field").each((i,el)=>{const fieldContainer=$(el);const name=fieldContainer.data("field");if(!this.specificFields.includes(name)){fieldContainer.find(".form-group").removeClass("hidden");}});}
parseError(error){if(typeof error==="string"){try{error=JSON.parse(error);}catch{}}
if(error&&typeof error==="object"){error=error.detail||JSON.stringify(error);}
return error||"Error getting models";}};